import { createReadStream } from 'node:fs';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

/**
 * File storage provider. The local-disk implementation is used in development and tests; an
 * S3-compatible implementation with the same interface (put, read, remove) can replace it in
 * production without touching callers.
 *
 * Keys are generated by the application ("<organizationId>/<uuid>.<ext>"), never taken from
 * user input. Every key is still checked to resolve inside the root directory, as a guard
 * against path traversal if that ever changes.
 */
const KEY_PATTERN = /^[0-9a-f-]{36}\/[0-9a-f-]{36}\.(jpg|png|webp)$/;

export function createLocalStorage({ rootDir }) {
  const root = path.resolve(rootDir);

  function resolveKey(key) {
    if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
    const full = path.resolve(root, key);
    if (!full.startsWith(root + path.sep)) throw new Error('Storage key escapes the root');
    return full;
  }

  return {
    async put(key, buffer) {
      const full = resolveKey(key);
      await mkdir(path.dirname(full), { recursive: true });
      // 'wx' fails if the file exists, so a key collision can never overwrite another file.
      await writeFile(full, buffer, { flag: 'wx' });
    },
    read(key) {
      return createReadStream(resolveKey(key));
    },
    async remove(key) {
      await rm(resolveKey(key), { force: true });
    },
  };
}
